        if(rd_mux_addr == 10'h1c8) begin
            readback_data_var[31:0] = hwif_in.COMPLETION_OUT_LEN.output1_len.next;
        end
        if(rd_mux_addr == 10'h1cc) begin
            readback_data_var[5:0] = hwif_in.COMPLETION_INFO.error_info.next;
            readback_data_var[31:6] = hwif_in.COMPLETION_INFO.cycles_quantized.next;
        end
        if(rd_mux_addr == 10'h1d0) begin
            readback_data_var[0] = field_storage.DOORBELL.doorbell.value;
        end
        if(rd_mux_addr == 10'h1d4) begin
            readback_data_var[31:0] = field_storage.DESC_ADDR_LO.desc_addr_lo.value;
        end
        if(rd_mux_addr == 10'h1d8) begin
            readback_data_var[7:0] = field_storage.DESC_ADDR_HI.desc_addr_hi.value;
        end
        if(rd_mux_addr == 10'h200) begin
            readback_data_var[7:0] = field_storage.KEY_SLOT_CTRL.slot_index.value;
            readback_data_var[10:8] = field_storage.KEY_SLOT_CTRL.key_type.value;
            readback_data_var[11] = field_storage.KEY_SLOT_CTRL.import_req.value;
            readback_data_var[12] = field_storage.KEY_SLOT_CTRL.destroy_req.value;
            readback_data_var[13] = field_storage.KEY_SLOT_CTRL.export_req.value;
            readback_data_var[14] = field_storage.KEY_SLOT_CTRL.lock_req.value;
        end
        if(rd_mux_addr == 10'h204) begin
            readback_data_var[7:0] = hwif_in.KEY_SLOT_META.owner.next;
            readback_data_var[10:8] = hwif_in.KEY_SLOT_META.algorithm.next;
            readback_data_var[14:11] = hwif_in.KEY_SLOT_META.parameter_set.next;
            readback_data_var[22:15] = hwif_in.KEY_SLOT_META.usage_mask.next;
            readback_data_var[23] = hwif_in.KEY_SLOT_META.exportable.next;
            readback_data_var[24] = hwif_in.KEY_SLOT_META.valid.next;
            readback_data_var[25] = hwif_in.KEY_SLOT_META.locked.next;
            readback_data_var[31:26] = hwif_in.KEY_SLOT_META.version.next;
        end
        if(rd_mux_addr == 10'h208) begin
            readback_data_var[15:0] = hwif_in.KEY_SLOT_GEN.generation.next;
        end
        if(rd_mux_addr == 10'h20c) begin
            readback_data_var[7:0] = hwif_in.KEY_SLOT_DOMAIN.domain.next;
        end
        for(int i0=0; i0<32; i0++) begin
            if(rd_mux_addr == 10'h210 + (10)'(i0) * 10'h4) begin
                readback_data_var[7:0] = hwif_in.KEY_SLOT_MIRROR[i0].slot_owner.next;
                readback_data_var[8] = hwif_in.KEY_SLOT_MIRROR[i0].slot_valid.next;
            end
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = decoded_err;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
